// Accumulate per bucket; on the tick, report rates over the last window.
// Buckets: "customer", "CH <serial> process", "CH <serial> waveforms", "CH <serial> other".
const acc = context.get("acc") || {};
const since = context.get("since") || Date.now();
if (msg.topic === "tick") {
    const dt = Math.max(1, (Date.now() - since) / 1000);
    const rows = Object.keys(acc).sort().map(k => ({
        bucket: k,
        msgs_per_s: +(acc[k].n / dt).toFixed(1),
        kbytes_per_s: +(acc[k].b / dt / 1024).toFixed(2)
    }));
    const total = rows.reduce((s, r) => s + r.kbytes_per_s, 0);
    context.set("acc", {});
    context.set("since", Date.now());
    node.status({fill: "grey", shape: "dot", text: `${total.toFixed(1)} KB/s on the broker`});
    msg.payload = {window_s: +dt.toFixed(0), total_kbytes_per_s: +total.toFixed(2), rows};
    return msg;
}
const t = msg.topic;
let bucket = "other";
if (t.startsWith("v1.0/DRWPA/")) bucket = "customer";
else if (t.startsWith("v1.0/CH/Fleet/")) {
    const p = t.split("/");
    const serial = p[5];
    const kind = t.endsWith("/Waveform") ? "waveforms" : (p[6] === "Events" || p[6] === "_meta") ? "events+meta" : "process";
    bucket = `CH ${serial} ${kind}`;
}
const a = acc[bucket] || {n: 0, b: 0};
a.n += 1;
a.b += msg.payload.length + t.length;
acc[bucket] = a;
context.set("acc", acc);
if (!context.get("since")) context.set("since", Date.now());
return null;

// Columns of the CSV: CH path -> column name. Add a line to add a column.
const COLS = {
    "Context/MW": "mw",
    "Context/NetHead_m": "net_head_m",
    "Cooling/WaterInletTemp": "cw_inlet_c",
    "Cooling/WaterFlow_TB": "cw_flow_tb_lps",
    "Bearings/TGB/PadTemp01": "tgb_pad1_c",
    "Bearings/TGB/PadTemp02": "tgb_pad2_c",
    "Bearings/TGB/PadTemp03": "tgb_pad3_c",
    "Bearings/TGB/PadTemp04": "tgb_pad4_c",
    "Bearings/TGB/OilTemp": "tgb_oil_c",
};
const THRUST = /^Bearings\/Thrust\/PadTemp\d\d$/;
const win = context.get("win") || {};           // serial -> {col: [sum, n]}
const minute = context.get("minute");
const now = Math.floor(Date.now() / 60000);
if (msg.topic === "tick") {
    if (minute === undefined) { context.set("minute", now); return null; }
    if (now === minute) return null;
    const out = [];
    const ts = new Date(minute * 60000).toISOString();
    for (const serial of Object.keys(win).sort()) {
        const row = {timestamp: ts, serial};
        for (const c of [...Object.values(COLS), "thrust_pad_max_c"]) {
            const s = win[serial][c];
            row[c] = s && s[1] ? +(s[0] / s[1]).toFixed(2) : "";
        }
        out.push(row);
    }
    context.set("win", {});
    context.set("minute", now);
    // one message per minute with every asset's row: one append, so the header check can't race
    return out.length ? {payload: out} : null;
}
const p = msg.topic.split("/");
const serial = p[5], path = p.slice(6).join("/");
const v = msg.payload;
if (!v || typeof v.value !== "number" || v.quality !== "GOOD") return null;
const w = win[serial] || (win[serial] = {});
const add = (c, x) => { const s = w[c] || (w[c] = [0, 0]); s[0] += x; s[1] += 1; };
if (COLS[path]) add(COLS[path], v.value);
if (THRUST.test(path)) {
    // hottest thrust pad: keep a per-second max, averaged over the minute
    const k = context.get("tmax") || {};
    const cur = k[serial] || {t: 0, max: -1e9};
    const sec = Math.floor(Date.now() / 1000);
    if (cur.t !== sec) { if (cur.t) add("thrust_pad_max_c", cur.max); k[serial] = {t: sec, max: v.value}; }
    else cur.max = Math.max(cur.max, v.value);
    context.set("tmax", k);
}
context.set("win", win);
return null;

// The header is written when the file is new or empty, so the file stays valid across restarts.
const FILE = env.get("BEARING_CSV_FILE") || "/data/exports/ch_bearings_1min.csv";
const rows = msg.payload;
const cols = Object.keys(rows[0]);
let header = "";
try {
    if (!fs.existsSync(FILE) || fs.statSync(FILE).size === 0) header = cols.join(",") + "\n";
} catch (e) { header = cols.join(",") + "\n"; }
msg.filename = FILE;
msg.payload = header + rows.map(r => cols.map(c => r[c]).join(",")).join("\n");
return msg;

const w = msg.payload;
const serial = msg.topic.split("/")[5];
const x = w.values, fs = w.sampleRate, n = x.length;
if (!n) return null;
const mean = x.reduce((s, v) => s + v, 0) / n;
let best = {f: 0, amp: 0};
const df = fs / n;                                   // 0.1 Hz for 1,000 samples at 100 S/s
for (let k = Math.ceil(0.2 / df); k * df <= 10; k++) {
    let re = 0, im = 0;
    for (let i = 0; i < n; i++) {
        const a = 2 * Math.PI * k * i / n;
        re += (x[i] - mean) * Math.cos(a);
        im -= (x[i] - mean) * Math.sin(a);
    }
    const amp = 2 * Math.sqrt(re * re + im * im) / n;   // amplitude in bar
    if (amp > best.amp) best = {f: k * df, amp};
}
const runner = (w.speedRpm || 0) / 60;
const ratio = runner > 0 ? best.f / runner : null;
const rope = ratio !== null && ratio >= 0.2 && ratio <= 0.4 && best.amp > 0.02;
node.status({fill: rope ? "yellow" : "grey", shape: "dot",
             text: `${serial}: ${best.f.toFixed(2)} Hz, ${best.amp.toFixed(3)} bar${rope ? " · vortex rope?" : ""}`});
msg.payload = {serial, timestamp: w.timestamp, dominant_hz: +best.f.toFixed(2), amplitude_bar: +best.amp.toFixed(4),
               runner_hz: +runner.toFixed(2), ratio: ratio === null ? null : +ratio.toFixed(3), rope_suspected: rope};
return msg;
